insert into data_features (layer_id, source, source_id, name, kind, geom, props, valid_from, valid_to) values
($q$restricoes_rmsp$q$, $q$itatiba$q$, $q$4d246d6a3ccf7736$q$, $q$Itatiba: Centro, quadrilátero das ruas Cel. Camilo Pires, Quintino Bocaiúva, Tobias Franco e Benjamin Constant, caminhão e trator das 10h às 18h de segunda a sábado$q$, $q$zona$q$, ST_SetSRID(ST_GeomFromGeoJSON($q${"type":"Polygon","coordinates":[[[-46.842982,-23.005093],[-46.842374,-23.003478],[-46.839557,-23.004362],[-46.837657,-23.004993],[-46.838053,-23.005838],[-46.838365,-23.006586],[-46.840951,-23.005719],[-46.842982,-23.005093]]]}$q$), 4326), $q${"regra_id":"itatiba_centro_quadrilatero","municipio":"Itatiba","ibge":"3523404","uf":"SP","tipo":"zona","regime":"Centro (quadrilátero)","nome":"Itatiba: Centro, quadrilátero das ruas Cel. Camilo Pires, Quintino Bocaiúva, Tobias Franco e Benjamin Constant, caminhão e trator das 10h às 18h de segunda a sábado","status":"ativa","confianca":"media","janelas":[{"days":[1,2,3,4,5,6],"from":"10:00","to":"18:00"}],"feriados":"aplica","alvo":{"caminhao":true},"origem_destino_dentro":"avisa","autorizacao":"Cadastro no Departamento Municipal de Trânsito (Lei 5.022/2017, art. 7º): VUC, veículos com 'Autorização Especial' e excepcionalidades","excecoes":["Lei 5.022/2017, art. 3º, parágrafo único: VUC cadastrado no Departamento Municipal de Trânsito","Lei 5.022/2017, art. 5º: não sujeitas à fiscalização as operações de carga e descarga de material de construção, remoção de terra e entulho e concretagem; em postos de combustíveis que não operam 24 h; em serviços de saúde em emergência","Dec. 3.644/1995, art. 1º: caminhões da ECT (Correios) ou contratada, no centro entre as ruas Florêncio Pupo e Benjamin Constant (carga e descarga seg–sex 8h–18h e sáb 8h–12h)"],"base_legal":[{"ato":"Lei municipal 2.455, de 31/03/1993 (Itatiba), com a redação da Lei 4.635, de 19/03/2014","artigo":"art. 1º (fica proibido o tráfego de caminhões e tratores no centro, no quadrilátero formado pelas ruas Camilo Pires, Quintino Bocaiúva, Tobias Franco e Benjamin Constant, nos termos do art. 2º)","url":"https://camaraitatiba.sp.gov.br/Siscam/Documentos/Details?id=124452"},{"ato":"Lei municipal 5.789, de 15/10/2025 (Itatiba)","artigo":"art. 1º (nova redação do art. 2º da Lei 2.455/1993: carga e descarga nas ruas do art. 1º das 18h às 10h, de segunda-feira a sábado)","url":"https://camaraitatiba.sp.gov.br/Siscam/Documentos/Details?id=196368"},{"ato":"Lei municipal 2.455, de 31/03/1993 (Itatiba), texto original","artigo":"art. 1º, parágrafo único (delimitação do quadrilátero)","url":"https://camaraitatiba.sp.gov.br/Siscam/Documentos/Details?id=122224"},{"ato":"Lei municipal 5.022, de 15/02/2017 (Itatiba)","artigo":"arts. 2º, 3º, parágrafo único, 5º e 7º (VUC e exceções)","url":"https://camaraitatiba.sp.gov.br/Siscam/Documentos/Details?id=145118"}],"nota":"Leitura: o tráfego de caminhão e trator no quadrilátero é proibido 'nos termos do art. 2º', que só abre a janela de carga e descarga das 18h às 10h de segunda a sábado (Lei 5.789/2025; antes era segunda a sexta). Logo, restrito das 10h às 18h de segunda a sábado. Domingo: o ato não fixa horário; a justificativa do PL 71/2025 fala em estender a proibição 'agora também aos sábados', isto é, domingo livre. O ato não excetua feriados. Geometria: as ruas-limite também contam ('ruas constantes do art. 1º'); o polígono foi desenhado 30 m por fora dos eixos das quatro ruas no OSM, para o recuo de 20 m da camada não liberá-las. A Lei 5.022/2017, art. 3º, caput, permite ao Departamento Municipal de Trânsito alterar a delimitação das vias por justificativa técnica (nenhuma alteração achada).","fonte_geometria":"Quadrilátero dos eixos das ruas Cel. Camilo Pires, Benjamin Constant, Tobias Franco e Quintino Bocaiúva no OSM (ODbL), com folga de 30 m para fora","vigencia_inicio":"2025-10-15","vuc":{"largura_max_m":2.2,"comprimento_max_m":6.3,"exige_cadastro":true,"orgao":"Departamento Municipal de Trânsito (Secretaria de Obras e Serviços Públicos)","artigo":"Lei 5.022/2017 (Itatiba), art. 2º (VUC: largura máxima 2,20 m, comprimento máximo 6,30 m e emissões PROCONVE L-5/P-6) e art. 3º, parágrafo único (VUC cadastrado no Departamento Municipal de Trânsito fica fora da proibição do centro); art. 7º, I (cadastro)","nota":"O requisito de emissões (PROCONVE) não está no perfil do veículo; a rota mantém a restrição e avisa (exige cadastro)."},"descricao":"Quadrilátero central de Itatiba (ruas Cel. Camilo Pires, Benjamin Constant, Tobias Franco e Quintino Bocaiúva), com as ruas-limite","folga_m":30.0,"verificado_em":"2026-10-11"}$q$::jsonb, $q$2025-10-15$q$::timestamptz, null::timestamptz),
